SELECT p.id AS position_id, w.execution_reason, e.generated_at AS e_gen, n.id AS late5_id, n.created_at AS late5_created, n.decision AS late5_decision, n.atr_immediate_entry_allowed AS late5_immediate, pv.id AS prev5_id, pv.decision AS prev5_decision, pv.atr_immediate_entry_allowed AS prev5_immediate, p.realized_pnl FROM paper_position p JOIN trade_signal e ON e.id=p.signal_id JOIN wallet_trade w ON w.signal_id=p.signal_id AND w.side='BUY' JOIN trade_signal n ON n.symbol=p.symbol AND n.interval_code='5m' AND n.generated_at BETWEEN e.generated_at - INTERVAL 3 SECOND AND e.generated_at + INTERVAL 5 SECOND AND n.created_at > e.generated_at LEFT JOIN trade_signal pv ON pv.id=(SELECT MAX(x.id) FROM trade_signal x WHERE x.symbol=p.symbol AND x.interval_code='5m' AND x.created_at <= e.generated_at) WHERE p.opened_at>='2026-10-11 00:00:00' ORDER BY p.id LIMIT 120